sysauto_script.script:
(function() {

    try {

        var nowGdt = new GlideDateTime();

        var configGR = new GlideRecord(
            'x_1893179_tisc_i_0_inbound_configurations'
        );

        configGR.addQuery(
            'active',
            true
        );

        configGR.addQuery(
            'type',
            'enrich_observables'
        );

        var nextRunQuery = configGR.addNullQuery(
            'next_run'
        );

        nextRunQuery.addOrCondition(
            'next_run',
            '<=',
            nowGdt
        );

        configGR.orderBy('next_run');

        configGR.query();

        var triggered = 0;

        if (!configGR.hasNext()) {

            gs.info(
                '[TISC Enrichment Scheduler] ' +
                'No due active Enrich Observables configurations found.'
            );

            return;
        }

        while (configGR.next()) {

            try {

                gs.info(
                    '[TISC Enrichment Scheduler] ' +
                    'Triggering enrichment for config: ' +
                    configGR.name
                );

                new x_1893179_tisc_i_0
                    .TISCObservableEnrichment()
                    .enrichObservables(
                        configGR.getUniqueValue()
                    );

                var nextRunGdt =
                    new GlideDateTime();

                var frequency =
                    parseInt(
                        configGR.import_frequency,
                        10
                    );

                if (isNaN(frequency) || frequency < 1) {
                    frequency = 1;
                }

                nextRunGdt.addDaysUTC(frequency);

                configGR.next_run =
                    nextRunGdt;

                configGR.update();

                triggered++;

            } catch (innerEx) {

                gs.error(
                    '[TISC Enrichment Scheduler] ' +
                    'Failed for config: ' +
                    configGR.name +
                    ' Error: ' +
                    innerEx.message
                );
            }
        }

        gs.info(
            '[TISC Enrichment Scheduler] ' +
            'Triggered ' +
            triggered +
            ' enrichment run(s).'
        );

    } catch (ex) {

        gs.error(
            '[TISC Enrichment Scheduler] Fatal error: ' +
            ex.message
        );
    }

})();
